--- Custom textures. The PNGs are generated by tools/build_assets.py into res/
--- and are not in git; without them the mod still runs, with vanilla looks.

local Assets = {}
SSB.Assets = Assets

local HERO_SHEET = "res/hero.png"

local hero_texture = nil
local replaced = {} -- vanilla texture id -> true, for undoing

--- The hero sheet has the layout of a vanilla character sheet (2048 x 2048, 128
--- pixel cells), so the definition is copied from one and only the file swapped.
local function define_hero()
    if hero_texture ~= nil then
        return hero_texture
    end
    if not PackFileExists(HERO_SHEET) then
        print("[SSB] " .. HERO_SHEET .. " is missing: run  python tools/build_assets.py"
            .. "  in the pack folder. Playing with the vanilla character for now.")
        return nil
    end
    local def = get_texture_definition(TEXTURE.DATA_TEXTURES_CHAR_YELLOW_0)
    def.texture_path = HERO_SHEET
    hero_texture = define_texture(def)
    return hero_texture
end

--- Give the player the hero's look. Replacing the character's own sheet (rather
--- than only the entity's texture) also covers the whip and the rope, which are
--- drawn from the same sheet.
--- @param p userdata
--- @return string # what happened, for the trace header
function Assets.dress_hero(p)
    local texture = define_hero()
    if texture == nil then
        return "hero texture: missing file"
    end
    local vanilla = p:get_texture()
    if vanilla == texture or replaced[vanilla] then
        return "hero texture: already applied"
    end
    if replace_texture(vanilla, texture) then
        replaced[vanilla] = true
        return "hero texture: replaced vanilla texture " .. tostring(vanilla)
    end
    p:set_texture(texture)
    return "hero texture: replace_texture refused, set on the entity only"
end

--- Put every replaced vanilla texture back.
function Assets.restore()
    for vanilla, _ in pairs(replaced) do
        pcall(reset_texture, vanilla)
    end
    replaced = {}
end

return Assets
